alter table cashflow.msp_task add column if not exists weekly_close_id uuid references cashflow.weekly_financial_close(id) on delete cascade,add column if not exists expected_cash_impact numeric(18,2),add column if not exists deep_link text;
alter table cashflow.msp_task drop constraint if exists msp_task_source_check;alter table cashflow.msp_task add constraint msp_task_source_check check(source in('MANUAL','RENEWAL','RISK','WEEKLY_CLOSE'));create unique index if not exists msp_task_weekly_close_slot_unique on cashflow.msp_task(weekly_close_id,title)where weekly_close_id is not null;
create or replace function cashflow.complete_weekly_close_with_plan(p_tenant_id uuid,p_as_of date,p_acknowledged boolean,p_note text default null)returns jsonb language plpgsql security definer set search_path=cashflow,public,pg_temp as $$declare v_uid uuid:=auth.uid();v_close uuid;v_model text;v_critical int;begin v_close:=cashflow.complete_weekly_close(p_tenant_id,p_as_of,p_acknowledged,p_note);select business_model into v_model from cashflow.tenant where id=p_tenant_id and owner_id=v_uid;v_critical:=coalesce((cashflow.financial_alert_center(p_tenant_id,p_as_of)#>>'{summary,critical}')::int,0);if v_model='startup-saas'then insert into cashflow.msp_task(tenant_id,owner_id,weekly_close_id,title,priority,assignee,due_date,source,deep_link)values(p_tenant_id,v_uid,v_close,case when v_critical>0 then'Resolver alertas críticas antes de aumentar el burn'else'Validar burn y runway contra el objetivo'end,case when v_critical>0 then'URGENT'else'HIGH'end,'Por asignar',p_as_of+2,'WEEKLY_CLOSE','/alerts'),(p_tenant_id,v_uid,v_close,'Revisar MRR, churn y renovaciones próximas','HIGH','Por asignar',p_as_of+4,'WEEKLY_CLOSE','/subscriptions#renewals'),(p_tenant_id,v_uid,v_close,'Definir una decisión de crecimiento basada en unit economics','MEDIUM','Por asignar',p_as_of+7,'WEEKLY_CLOSE','/weekly-close')on conflict do nothing;else insert into cashflow.msp_task(tenant_id,owner_id,weekly_close_id,title,priority,assignee,due_date,source,deep_link)values(p_tenant_id,v_uid,v_close,case when v_critical>0 then'Priorizar cobros y obligaciones que presionan la caja'else'Revisar facturas próximas a vencer'end,case when v_critical>0 then'URGENT'else'HIGH'end,'Por asignar',p_as_of+2,'WEEKLY_CLOSE','/operations#collections'),(p_tenant_id,v_uid,v_close,'Confirmar nómina, impuestos y proveedores de la semana','HIGH','Por asignar',p_as_of+4,'WEEKLY_CLOSE','/operations#recurring'),(p_tenant_id,v_uid,v_close,'Proteger margen antes de asumir nuevos gastos','MEDIUM','Por asignar',p_as_of+7,'WEEKLY_CLOSE','/weekly-close')on conflict do nothing;end if;return jsonb_build_object('close_id',v_close,'action_count',(select count(*)from cashflow.msp_task where weekly_close_id=v_close and owner_id=v_uid));end$$;
create or replace function cashflow.financial_action_plan_workspace(p_tenant_id uuid)returns jsonb language sql stable security invoker set search_path=cashflow,public as $$select jsonb_build_object('open_count',count(*)filter(where status<>'DONE'),'done_count',count(*)filter(where status='DONE'),'overdue_count',count(*)filter(where status<>'DONE'and due_date<current_date),'actions',coalesce(jsonb_agg(jsonb_build_object('id',id,'title',title,'priority',priority,'status',status,'assignee',assignee,'due_date',due_date,'expected_cash_impact',expected_cash_impact,'deep_link',deep_link,'weekly_close_id',weekly_close_id)order by case status when'DONE'then 2 else 1 end,case priority when'URGENT'then 1 when'HIGH'then 2 when'MEDIUM'then 3 else 4 end,due_date)filter(where id is not null),'[]'::jsonb))from cashflow.msp_task where tenant_id=p_tenant_id and owner_id=auth.uid()and source='WEEKLY_CLOSE'$$;
revoke all on function cashflow.complete_weekly_close_with_plan(uuid,date,boolean,text),cashflow.financial_action_plan_workspace(uuid)from public,anon;grant execute on function cashflow.complete_weekly_close_with_plan(uuid,date,boolean,text),cashflow.financial_action_plan_workspace(uuid)to authenticated;
